  const mismatch=await call('/api/documents/incident-alpha',{method:'PUT',headers,body:JSON.stringify({...changed,id:'other',baseRevision:2})});
  const unknown=await call('/api/documents/no-such-document',{method:'PUT',headers,body:JSON.stringify({...changed,id:'no-such-document',baseRevision:2})});
  const latest=(await call('/api/documents/incident-alpha')).body.document;
  const revisions=(await call('/api/documents/incident-alpha/revisions')).body.revisions;
  console.log(JSON.stringify({saved:[saved.status,saved.body.document?.currentRevision],unchanged:[unchanged.status,unchanged.body.unchanged],stale:[stale.status,stale.body.currentRevision],mismatch:mismatch.status,unknown:unknown.status,latest:[latest.currentRevision,latest.content.endsWith('Verification edit')],revisionCount:revisions.length},null,2));
